// Access the first (and only) item from the Aggregate node
const input = $input.first().json;
const content = input.content;

// Helper to navigate that specific double-array structure
const getValue = (index) => {
  try {
    // The path is now: content[index][0].text...
    return content[index][0].text.results[0].data_points[0].value;
  } catch (e) {
    return 0;
  }
};

return [{
  json: {
    sessions: {
      previous: getValue(0),
      current: getValue(1)
    },
    new_users: {
      previous: getValue(2),
      current: getValue(3)
    },
    ads_cost: {
      previous: getValue(4),
      current: getValue(5)
    },
    ads_clicks: {
      previous: getValue(6),
      current: getValue(7)
    }
  }
}];

